Clinical & EMR Core Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(clinical_emr_core_container, "Clinical & EMR Core Container") {
    Component(patient_demographic_service, "Patient Demographic Service", "Spring Boot / Java", "Manages and retrieves patient demographic information.")
    Component(scheduling_engine, "Scheduling Engine", "Spring Boot / Java", "Handles appointment scheduling and clash checks.")
    Component(emr_management_service, "EMR Management Service", "Spring Boot / Java", "Manages electronic medical records operations.")
    Component(audit_compliance_interceptor, "Audit & Compliance Interceptor", "Spring Boot / Java (AOP)", "Ensures HIPAA/GDPR compliance via asynchronous auditing.")
    Component(local_state_cache_sync_coordinator, "Local State Cache & Sync Coordinator", "Caffeine Cache & Embedded RocksDB", "Provides transient local state cache for offline resilience.")
}

Rel(emr_management_service, local_state_cache_sync_coordinator, "Accesses cached patient data", "In-Memory / Local IPC")

@enduml

Edge Sync Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(edge_sync_container, "Edge Sync Container") {
    Component(Outbox_Poller, "Outbox Poller", "Go Daemon", "Reads un-synced events from the Primary DB & Audit Store using the transactional outbox pattern.")
    Component(Encryption___Transformer, "Encryption & Transformer", "Go Daemon", "Encrypts and transforms offline patient care and transactional data for secure transmission.")
    Component(Cloud_Sync_Client, "Cloud Sync Client", "Go Daemon / gRPC over mTLS", "Syncs encrypted data to the cloud tier over secure channels.")
    Component(DLQ___Spool_Manager, "DLQ & Spool Manager", "Go Daemon / Local Disk Spooling", "Manages local disk spooling and dead-letter queues to ensure offline resilience and fault tolerance.")
}

Rel(Outbox_Poller, Encryption___Transformer, "Passes un-synced events")
Rel(Encryption___Transformer, Cloud_Sync_Client, "Sends encrypted payloads")
Rel(Cloud_Sync_Client, DLQ___Spool_Manager, "Handles delivery failures and spools data")

@enduml
